public class Radar : MonoBehaviour
{
    NativeArray<float3> positions;   // Persistent, filled in Awake
    NativeArray<float> weights;      // Persistent, filled in Awake
    NativeList<int> visible;         // Persistent, capacity = positions.Length
    NativeReference<float> total;    // Persistent
    JobHandle handle;

    void Update()
    {
        visible.Clear();
        var cull = new CullJob { positions = positions, camera = transform.position,
                                 maxDistSq = 2500f, visible = visible.AsParallelWriter() };
        var sum = new SumJob { visible = visible, weights = weights, total = total };
        JobHandle culled = cull.Schedule(positions.Length, 64);
        handle = sum.Schedule(culled);          // runs after the cull, no wait here
        JobHandle.ScheduleBatchedJobs();
    }

    void LateUpdate()
    {
        handle.Complete();                      // completes the whole chain
        ShowOnRadar(total.Value);
    }
}

