JobHandle ScheduleHeat(NativeArray<float3> positions, NativeArray<float> heat)
{
    var tmp = new NativeArray<float>(positions.Length, Allocator.TempJob);
    JobHandle a = new SampleJob { positions = positions, tmp = tmp }.Schedule(positions.Length, 64);
    JobHandle b = new BlurJob { src = tmp, dst = heat }.Schedule(positions.Length, 64);
    b.Complete();
    a.Complete();
    tmp.Dispose();
    return b;
}

