JobHandle ScheduleHeat(NativeArray<float3> positions, NativeArray<float> heat)
{
    var tmp = new NativeArray<float>(positions.Length, Allocator.TempJob);
    JobHandle a = new SampleJob { positions = positions, tmp = tmp }.Schedule(positions.Length, 64);
    JobHandle b = new BlurJob { src = tmp, dst = heat }.Schedule(positions.Length, 64, a);  // reads tmp after a
    // no Complete here: the caller completes the returned handle later
    JobHandle freed = tmp.Dispose(b);   // a job frees tmp after the blur
    return freed;
}

